int compute(int *a, int *b, int *sum) {
    if (*a < *b) {
        int temp = *a;
        *a = *b;
        *b = temp;
        *sum += (*a - *b);
    } else {
        *sum += (*a + *b);
    }
    return *sum;
}

int main(void) {
    int x = 12;
    int y = 18;
    int total = 0;
    int res1 = compute(&x, &y, &total);
    int res2 = compute(&x, &y, &total);
    printf("%d, %d, %d", x, y, res2);
    return 0;
}

