#include <stdio.h>

typedef struct {
    int id;
    int value;
} Item;

int processItems(Item *p, int size) {
    int total = 0;
    for(int i = 0; i < size; i++) {
        if ((p + i)->value % 2 == 0) {
            (p + i)->value += (p + i)->id;
        } else {
            (p + i)->value -= (p + i)->id;
        }
        total += (p + i)->value;
    }
    return total;
}

int main(void) {
    Item items[3] = {
        {1, 10},
        {2, 20},
        {3, 30}
    };

    int result = processItems(items, 3);
    printf("%d", result);
    return 0;
